                                elif 'The file' in txt and 'edited' in txt:
                                    edit_results.append(('OK', txt[:100]))
    except:
        pass

print(f'Edit results found: {len(edit_results)}')
errors = [(t,m) for t,m in edit_results if t == 'ERROR']
ok = [(t,m) for t,m in edit_results if t == 'OK']
print(f'Errors: {len(errors)}, OK: {len(ok)}')
if errors:
    for t,m in errors:
        print('ERROR:', m)
